import{_ as p,r as n,o,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"用户 - October CMS - 3.x","titleTemplate":false,"description":"了解后台面板的用户管理。","frontmatter":{"subtitle":"了解后台面板的用户管理。"},"headers":[{"level":2,"title":"后台用户助手","slug":"后台用户助手","link":"#后台用户助手","children":[]},{"level":2,"title":"分组","slug":"分组","link":"#分组","children":[]},{"level":2,"title":"更改后台用户密码","slug":"更改后台用户密码","link":"#更改后台用户密码","children":[]}],"relativePath":"3.x/zh-cn/extend/backend/users.md","filePath":"3.x/zh-cn/extend/backend/users.md"}'),i={name:"3.x/zh-cn/extend/backend/users.md"};function u(k,s,d,g,h,m){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(e),s[0]||(s[0]=l("h1",null,"用户",-1)),a(t),s[1]||(s[1]=r(`<p>后台面板的用户管理基于管理员，其中 <code>Backend\\Models\\User</code> 模型是保存用户所有重要信息的容器。它包括角色、分组、权限、密码重置和登录限流等功能。插件还可以<a href="./permissions.html">注册权限</a>来控制对后台功能的访问。</p><h2 id="后台用户助手"><a href="#后台用户助手" class="header-anchor">#</a> 后台用户助手</h2><p>全局 <code>BackendAuth</code> facade 可用于管理管理用户，它主要继承自 <code>October\\Rain\\Auth\\Manager</code> 类。要注册新的管理用户帐户，请使用 <code>BackendAuth::register</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Some&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;last_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;some@website.tld&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>BackendAuth::check</code> 方法是快速检查用户是否已登录的方式。要返回已登录的用户模型，请使用 <code>BackendAuth::getUser</code>。此外，活动用户在任何<a href="./../system/controllers.html">后台控制器</a>中都可以通过 <code>$this-&gt;user</code> 获取。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns true if signed in.</span>
<span class="token variable">$loggedIn</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Returns the signed in user</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以使用 <code>BackendAuth::findUserByLogin</code> 方法通过登录名查找用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">findUserByLogin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以使用 <code>BackendAuth::authenticate</code> 通过提供登录名和密码来验证用户身份。您也可以通过将 <code>Backend\\Models\\User</code> 模型传递给 <code>BackendAuth::login</code> 来直接以用户身份登录。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Authenticate user by credentials</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">authenticate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Sign in as a specific user</span>
<span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">login</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="分组"><a href="#分组" class="header-anchor">#</a> 分组</h2><p>用户分组使用 <code>Backend\\Models\\UserGroup</code> 模型，是用于对管理员进行分组的组织工具，它们与<a href="./permissions.html">用户权限</a>无关，严格用于组织目的，例如通知。</p><p>例如，如果您想向 <code>Head Office Staff</code> 分组中的所有用户发送电子邮件，您可以找到该用户分组及其中的用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$group</span> <span class="token operator">=</span> <span class="token class-name static-context">UserGroup</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;code&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;head-office-staff&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$group</span><span class="token operator">-&gt;</span><span class="token property">users</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;author.plugin:important_notification&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="更改后台用户密码"><a href="#更改后台用户密码" class="header-anchor">#</a> 更改后台用户密码</h2><p><code>october:passwd</code> 命令允许通过命令行更改后台管理员的密码。如果您被锁定在 October CMS 安装之外，或需要更改默认管理员帐户的密码，这很有用。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:passwd username password
</code></pre></div><p>第一个参数可以传递登录名或电子邮件地址。第二个参数可以选择性地传递所需的密码，否则将提示您输入密码。</p>`,18))])}const v=p(i,[["render",u]]);export{_ as __pageData,v as default};
